// 查询 5xx 错误
{
  "query": {
    "bool": {
      "must": [
        { "range": { "status": { "gte": 500, "lt": 600 } } },
        { "range": { "@timestamp": { "gte": "now-1h" } } }
      ]
    }
  },
  "sort": [{ "@timestamp": "desc" }]
}

// 查询高延迟请求
{
  "query": {
    "bool": {
      "must": [
        { "range": { "request_time": { "gte": 1 } } },
        { "range": { "@timestamp": { "gte": "now-1h" } } }
      ]
    }
  }
}

